"use client"

// Eagle (generated by ascii-video-playground).
// Assets: /videos/aguilanegro.webm (black background, blend "screen"), /videos/aguilacolor-v2.webm
// The colour-grade shader in the config is compiled at runtime by Shader Lab; baking the grade into the clips would be cheaper.
// Runs on the shared cheap engine (ascii-video-runtime.tsx): 960x540, paused off-screen, plain videos on weak devices.
// Stop-motion: rendered at 12 fps (the engine default).

import type { ShaderLabConfig } from "@basementstudio/shader-lab"
import { AsciiVideoRuntime, type ProbeSetter } from "./ascii-video-runtime"
import { withGlyphHover } from "./ascii-hover-layer"

