/** The composition plus the local black/white point layer used while hovering (panel: ASCII videos · glyph hover). */
const HOVER_ID = "eagle"
const config = withGlyphHover(baseConfig, HOVER_ID)

/** [with-background clip (master clock), black-background cutout clip] */
const SOURCES = ["/videos/aguilacolor-v2.webm", "/videos/aguilanegro.webm"] as const

/** Render rate: 12 fps for the stop-motion look. */
const FPS = 12

export function AsciiVideo({ className, allowMobile, onProbe }: { className?: string; allowMobile?: boolean; onProbe?: ProbeSetter }) {
  return <AsciiVideoRuntime config={config} sources={SOURCES} className={className} fps={FPS} allowMobile={allowMobile} onProbe={onProbe} hoverId={HOVER_ID} />
}
